import { FormField } from '../FormField';
import { ImageUpload } from '../ImageUpload';

interface MedtechAssociateCompaniesFormProps {
  formData: any;
  handleInputChange: (key: string, value: any) => void;
  uploadImage?: (file: File) => Promise<number | null>;
  uploadingImage?: boolean;
  errors?: Record<string, string>;
}

export const MedtechAssociateCompaniesForm = ({
  formData,
  handleInputChange,
  uploadImage,
  uploadingImage,
  errors = {}
}: MedtechAssociateCompaniesFormProps) => {
  const companies = Array.isArray(formData.companies)
    ? formData.companies
    : (formData.companies
        ? (() => {
            try {
              return JSON.parse(formData.companies);
            } catch {
              return [
                { name: '', logo: '', description: '' },
                { name: '', logo: '', description: '' }
              ];
            }
          })()
        : [
            { name: '', logo: '', description: '' },
            { name: '', logo: '', description: '' }
          ]);

  const updateCompany = (index: number, field: string, value: string | number) => {
    const updated = [...companies];
    updated[index] = { ...updated[index], [field]: value };
    handleInputChange('companies', updated);
  };

  const addCompany = () => {
    handleInputChange('companies', [...companies, { name: '', logo: '', description: '' }]);
  };

  const removeCompany = (index: number) => {
    const updated = companies.filter((_: any, i: number) => i !== index);
    handleInputChange('companies', updated);
  };

  return (
    <div className="space-y-4">
      <FormField
        label="Section Heading"
        name="title"
        value={formData.title || ''}
        onChange={(value) => handleInputChange('title', value)}
        required
        error={errors.title}
      />

      <div className="border-2 border-gray-200 rounded-lg p-4 bg-gray-50">
        <div className="flex justify-between items-center mb-4">
          <h4 className="font-semibold text-gray-900">Associate Companies</h4>
          <button
            type="button"
            onClick={addCompany}
            className="px-3 py-1.5 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 transition-colors"
          >
            <i className="ri-add-line"></i> Add Company
          </button>
        </div>
        <div className="space-y-3">
          {companies.length > 0 ? (
            companies.map((company: any, index: number) => (
              <div
                key={index}
                className="space-y-3 p-4 border border-gray-200 rounded-lg bg-white"
              >
                <div className="flex justify-between items-center">
                  <p className="text-sm font-semibold text-gray-700">
                    Company {index + 1}
                  </p>
                  <button
                    type="button"
                    onClick={() => removeCompany(index)}
                    className="px-2 py-1 text-red-600 hover:bg-red-50 rounded transition-colors"
                    title="Remove company"
                  >
                    <i className="ri-delete-bin-line"></i>
                  </button>
                </div>

          <FormField
            label="Name"
            name={`company-${index}-name`}
            value={company.name || ''}
            onChange={(value) => updateCompany(index, 'name', value)}
            required
            error={errors[`companies[${index}].name`]}
          />

          <ImageUpload
            label="Logo"
            value={company.logo || ''}
            onChange={(value) => updateCompany(index, 'logo', value)}
            onUpload={uploadImage}
            uploading={uploadingImage || false}
            error={errors[`companies[${index}].logo`]}
            fileType="logo"
            allowUrl={true}
          />

          <FormField
            label="Description"
            name={`company-${index}-description`}
            type="textarea"
            rows={4}
            value={company.description || ''}
            onChange={(value) => updateCompany(index, 'description', value)}
            error={errors[`companies[${index}].description`]}
                />
              </div>
            ))
          ) : (
            <p className="text-gray-400 text-sm italic">
              No companies added yet. Click "Add Company" to add associate companies.
            </p>
          )}
        </div>
      </div>
    </div>
  );
};


